<script setup>
import { onMounted } from 'vue'; import { useRouter } from 'vue-router'; import { useAutopeer } from '../../state/autopeer';
const s=useAutopeer(), router=useRouter(); onMounted(()=>{if(!s.currentUser.value)s.bootstrap()}); const title=n=>n.peering?.display_name||n.name||n.id
</script>
<template><section class="page-heading"><div><p class="eyebrow">AVAILABLE LOCATIONS</p><h1>All nodes</h1><p>Choose a node to create a new peer session or manage sessions on that node.</p></div></section><section class="node-grid"><mdui-card v-for="node in s.nodes.value" :key="node.id" class="node-card compact-node" variant="outlined"><div class="node-summary"><div><p class="eyebrow">{{node.id}}</p><h2>{{title(node)}}</h2><p>{{node.peering?.subtitle||'DN42 WireGuard peering'}}</p></div><span class="stack-pill">{{node.peering?.protocol_stack||'Dual stack'}}</span></div><div class="node-metrics"><div><span>Peers</span><strong>{{node.peer_count??0}} total</strong></div><div><span>Traffic</span><strong>↓ {{s.formatBytes(node.runtime_metrics?.rx_bytes)}} · ↑ {{s.formatBytes(node.runtime_metrics?.tx_bytes)}}</strong></div></div><div class="node-actions"><mdui-button variant="filled" :disabled="!node.peering_enabled" @click="s.openCreate(node);router.push({name:s.isAdmin.value?'admin-peer-create':'peer-create',params:{node:node.id}})">Start peering</mdui-button></div></mdui-card></section></template>